    return G
G=load(); print(sorted(G))
for name in ['Demo pair 1','Demo pair 2']:
    A=np.array(G[name+' input']); B=np.array(G[name+' output'])
    Ha,Wa=A.shape
    cnt=Counter(A.flatten())
    bg=cnt.most_common(1)[0][0]
    others={c:n for c,n in cnt.items() if c!=bg}
    val=max(others,key=lambda c:others[c])
    sc=[tuple(p.tolist()) for p in np.argwhere(A==val)]
    sb=set(map(tuple,np.argwhere(B==val)))
    extras=sb-set(sc)
    print('===',name,'seed size',len(sc),'added',len(extras))
    cands=[]
    for dr in range(-Ha,Ha+1):
        for dc in range(-Wa,Wa+1):
            t={p+(dr,dc) for p in sc}
            if t<=extras: cands.append((dr,dc,len(t)))
    print('exact-match candidates (shift, covered):', sorted(cands, key=lambda x:-x[2]))

