def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def solve(g):
    H=len(g); W=len(g[0])
    cnt=Counter(x for row in g for x in row)
    mc=cnt.most_common()
    bg=mc[0][0]
    # noise = the most common color that isn't bg or fill; choose: second-most-common overall
    others=[c for c,n in mc if c!=bg]
    fill=Counter(others).most_common(1)[0][0]
    noise=[c for c,n in cnt.items() if c not in (bg,fill)][0]
    S=[(r,c) for r in range(H) for c in range(W) if g[r][c]==fill]
    res=[row[:] for row in g]
    shifts=set()
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            if all(0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]!=bg for r,c in S):
                shifts.add((dr,dc))
    for dr,dc in shifts:
        for r,c in S:
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and g[rr][cc] in (0,noise):
                res[rr][cc]=fill
    return res
for k in ['Demo pair 3','Demo pair 4','Demo pair 5','Demo pair 6']:
    print(k,'match:',solve(G[k+' input'])==G[k+' output'])
print(json.dumps(solve(G['Test input'])))

