# rule for demo5: shifts with NO overlap of original shape -> paint. (-1,2),(0,0) overlap orig shape so don't paint; others pure-0 translations -> paint.
def solve(g):
    H=len(g); W=len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    fill=[c for c,n in cnt.items() if c!=bg and c!=0][0]
    S=[(r,c) for r in range(H) for c in range(W) if g[r][c]==fill]
    res=[row[:] for row in g]
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            targets=set(r+dr,c+dc for r,c in S if 0<=r+dr<H and 0<=c+dc<W)
            if targets & set(S): continue
            if all(g[r][c]==0 for r,c in targets):
                for r,c in targets:
                    res[r][c]=fill
    return res
