from collections import Counter
def comps(g,v):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==v and not seen[r][c]:
                st=[(r,c)]; sset={(r,c)}; seen[r][c]=True
                while st:
                    a,b=st.pop()
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==v and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y)); sset.add((x,y))
                out.append(sset)
    return out
